// AUTO-GENERATED from src/panel_page.html + src/dashboard.html — DO NOT EDIT BY HAND.
// Re-run: pnpm --filter @workspace/boosthis-runtime-node run build-kit-assets
//
// Embedded rather than read from disk so a BUNDLED install serves the real
